using namespace std;

struct Half {
    long long match;
    long long value;
    Half() : match(0), value(0) {}
    Half(long long m, long long v) : match(m), value(v) {}
    bool operator<(const Half& o) const {
        return value < o.value;
    }
};

class F3 {
private:
    vector<vector<long long>> ways;
    long long totalWays;
    long long bestDiff;
    long long ans;
    istringstream iss;
    string line;

    int trailingZeros(unsigned int x) {
        if (x == 0) return 32;
        return __builtin_ctz(x);
    }

    int bitCount(unsigned int x) {
        return __builtin_popcount(x);
    }

    long long choose(int n, int k) {
        if (n >= 0 && k >= 0 && k <= n) return ways[n][k];
        return 0;
    }

    bool test(int mask, int i) {
        return ((mask >> i) & 1) == 1;
    }

    vector<Half> compress(vector<Half>& arr) {
        sort(arr.begin(), arr.end());
        vector<Half> res;
        for (size_t i = 0; i < arr.size(); ++i) {
            if (res.empty() || res.back().value != arr[i].value) {
                res.push_back(arr[i]);
            } else {
                res.back().match += arr[i].match;
            }
        }
        return res;
    }

    void update(Half a, Half b) {
        long long totalValue = a.value + b.value;
        long long diff = llabs(2 * totalValue - totalWays);
        long long delta = a.match * b.match;
        if (diff < bestDiff) {
            bestDiff = diff;
            ans = delta;
        } else if (diff == bestDiff) {
            ans += delta;
        }
    }

    long long solve(int r, int c, const string& s) {
        bestDiff = LLONG_MAX;
        ans = 0;

        long long maskA = 0;
        long long maskB = 0;
        vector<vector<int>> cnt(s.length() + 1, vector<int>(2, 0));
        for (size_t i = 0; i < s.length(); ++i) {
            cnt[i + 1][0] = cnt[i][0];
            cnt[i + 1][1] = cnt[i][1];
            if (s[i] == 'A') {
