                if (i < 64) maskA |= 1LL << i;
            }
            if (s[i] == 'B') {
                cnt[i + 1][1]++;
                if (i < 64) maskB |= 1LL << i;
            }
        }

        int shift = (2 * r + c - 1) & 63;
        long long lastA = maskA >> shift;
        long long lastB = maskB >> shift;

        vector<vector<Half>> fst(c + 2);
        vector<vector<Half>> snd(c + 2);
        vector<int> sz(c + 2);
        for (int i = 0; i < c + 2; ++i) {
            sz[i] = (int)ways[c + 1][i];
            fst[i].resize(sz[i]);
            snd[i].resize(sz[i]);
        }

        for (int mask = 0; mask < (1 << (c + 1)); ++mask) {
            int btc = bitCount(mask);
            int compBtc = c + 1 - btc;
            int idx = --sz[btc];

            // first half
            {
                int samePref = min(trailingZeros((mask & 1) == 0 ? mask : (mask + 1)), c + 1);
                int totalA = r - 1 - cnt[2 * r - 2 + samePref][0];
                int totalB = r - 1 - cnt[2 * r - 2 + samePref][1];
                if ((mask & 1) == 0) {
                    totalA += samePref;
                } else {
                    totalB += samePref;
